<template>
  <section class="environment-model">
    <template v-if="mode==='world'"><header><div><small>领域模型 / 世界输入</small><h2>铀供应链世界模型</h2><p>统一世界边界、空间网络、时间推进和状态更新顺序。</p></div><el-button type="primary" @click="applyWorld">应用世界设定</el-button></header><div class="time-window"><label>世界名称<el-input v-model="world.name"/></label><label>产品口径<el-input v-model="world.product"/></label><label>单位<el-input v-model="world.quantity_unit"/></label><label>时间步（天）<el-input-number v-model="world.step_days" :min="0.01" :max="365"/></label><label>开始日期<el-input v-model="world.start_date" type="date"/></label><label>结束日期<el-input v-model="world.end_date" type="date"/></label></div><el-input v-model="world.boundary" type="textarea" :rows="2"/><div class="events"><h3>{{ world.nodes.length }} 个业务主体 · {{ world.edges.length }} 条供需 / 通道关系</h3><p>{{ world.source }} · {{ world.coordinate_basis }}</p><div class="roles"><span v-for="(step,index) in world.update_order" :key="step">{{ index+1 }}. {{ step }}</span></div><div v-for="node in world.nodes" :key="node.entity_id" class="coupling-row"><strong>{{ node.name }}</strong><p>{{ node.description }}</p></div></div></template>
    <template v-else><header><div><small>领域模型 / 环境输入</small><h2>供应链环境模型</h2><p>环境参数来自同一领域框架，向各类 Agent 提供外部条件、约束和事件输入。</p></div><div><el-button @click="exportInput">导出环境输入</el-button><el-button type="primary" @click="apply">应用到领域框架</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <div class="time-window"><label>环境步长（天）<el-input-number v-model="draft.time_step_days" :min="0.01" :max="365"/></label><label>开始日期<el-input v-model="draft.start_date" type="date"/></label><label>结束日期<el-input v-model="draft.end_date" type="date"/></label></div>
    <div class="layer-grid"><article v-for="layer in layers" :key="layer.id"><h3>{{ layer.label }}</h3><p>{{ layer.description }}</p><div v-for="field in draft.fields.filter(x=>x.layer===layer.id)" :key="field.id" class="environment-field"><div><strong>{{ field.label }}</strong><el-tag size="small" :type="field.source==='unbound'?'warning':field.source==='framework_default'?'info':'success'">{{ sourceLabel(field) }}</el-tag></div><div class="value-row"><el-input-number :model-value="field.value" :min="field.min" :max="field.max??undefined" :step="field.unit==='1'?0.05:1" @update:model-value="bindValue(field,$event)"/><span>{{ field.unit }}</span></div><small>领域输入：{{ field.domain_input ? inputLabel(field.domain_input) : '环境专属参数' }}</small><p>{{ field.effect }}</p><div class="roles"><span v-for="actor in field.actor_types" :key="actor">{{ typeLabel(actor) }}</span></div></div></article></div>
    <section class="events"><div class="section-head"><div><h3>外部事件与作用范围</h3><p>定义何时、对谁、以何值覆盖环境参数；保留时间顺序，作为建模输入导出。</p></div><el-button @click="addEvent">＋扰动事件</el-button></div><p v-if="!draft.events.length">当前未配置扰动事件。可添加通道受阻、产能下降、需求冲击或政策调整。</p><div v-for="(event,index) in draft.events" :key="event.id" class="event-row"><el-input v-model="event.label" placeholder="事件名称"/><el-select v-model="event.parameter_id" placeholder="作用参数"><el-option v-for="field in draft.fields" :key="field.id" :value="field.id" :label="field.label"/></el-select><el-select v-model="event.actor_types" multiple placeholder="受影响Agent"><el-option v-for="actor in actors" :key="actor.id" :value="actor.id" :label="actor.label"/></el-select><label>起始步<el-input-number v-model="event.start_step" :min="0" :precision="0"/></label><label>结束步<el-input-number v-model="event.end_step" :min="0" :precision="0"/></label><label>覆盖值<el-input-number v-model="event.value" :min="0"/></label><el-button text type="danger" @click="draft.events.splice(index,1)">删除</el-button></div></section>
    <section class="coupling"><h3>环境 → Agent 的输入映射</h3><div v-for="actor in actors" :key="actor.id" class="coupling-row"><strong>{{ actor.label }}</strong><p>{{ draft.fields.filter(x=>x.actor_types.includes(actor.id)).map(x=>`${x.label} → ${x.effect.split(' → ').at(-1)}`).join('；') }}</p></div></section>
    </template><p class="footnote">框架默认值是可编辑的建模基线；未提供的价格、配额和时间范围保持待补全。此页只组织前端建模输入。</p>
  </section>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { buildEnvironmentModel,environmentLayers,validateEnvironment } from '@/utils/domainEnvironmentModel'
const props=defineProps({model:{type:Object,required:true},mode:{type:String,default:'environment'}}),emit=defineEmits(['update-environment','update-world'])
const world=ref(JSON.parse(JSON.stringify(props.model.world_model)))
const draft=ref(null),error=ref(''),layers=environmentLayers
const actors=computed(()=>props.model.types.filter(x=>['supplier','manufacturer','demander','logistics','warehouse'].includes(x.id)))
watch(()=>props.model.environment_model,()=>{draft.value=JSON.parse(JSON.stringify(buildEnvironmentModel(props.model)))},{immediate:true,deep:true})
const inputLabel=id=>props.model.inputs.find(x=>x.id===id)?.label||id
const typeLabel=id=>props.model.types.find(x=>x.id===id)?.label||id
const sourceLabel=field=>field.value==null?'待补全':field.source==='framework_default'?'框架默认值':'用户已绑定'
function bindValue(field,value){field.value=Number.isFinite(value)?value:null;field.source=field.value==null?'unbound':'user_bound'}
function addEvent(){draft.value.events.push({id:'event_'+Date.now(),label:'',parameter_id:'capacity_availability',actor_types:['manufacturer'],start_step:0,end_step:1,value:0.5,operation:'override'})}
function applyWorld(){if(!world.value.name.trim()||!world.value.product.trim()||!Number.isFinite(world.value.step_days)||world.value.step_days<=0||world.value.end_date&&world.value.start_date&&world.value.end_date<world.value.start_date){ElMessage.error('请检查世界名称、产品和时间设置');return}emit('update-world',JSON.parse(JSON.stringify(world.value)));ElMessage.success('世界设定已应用到领域框架')}
function apply(){const result=validateEnvironment(draft.value);error.value=result.errors.join('；');if(!result.valid)return false;emit('update-environment',JSON.parse(JSON.stringify(draft.value)));ElMessage.success('环境定义已应用，Agent建模输入同步更新');return true}
function exportInput(){if(!apply())return;const url=URL.createObjectURL(new Blob([JSON.stringify(draft.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='供应链环境建模输入.json';a.click();URL.revokeObjectURL(url)}
</script>
<style scoped>
.environment-model{padding:24px;color:#25364f}.environment-model header,.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.environment-model h2{font-size:21px;margin:8px 0}.environment-model header small{color:#2563eb}.environment-model p{font-size:12px;line-height:1.9;color:#64748b}.time-window{display:flex;flex-wrap:wrap;gap:20px;background:#f1f5f9;padding:18px;margin:20px 0;border-radius:9px}.time-window label{display:flex;align-items:center;gap:10px;font-size:12px}.time-window .el-input{width:160px}.layer-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.layer-grid article{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:18px}.layer-grid h3{font-size:15px;margin:0}.environment-field{border-top:1px solid #e2e8f0;margin-top:14px;padding-top:14px}.environment-field>div:first-child{display:flex;align-items:center;justify-content:space-between;gap:8px}.environment-field strong{font-size:12px}.value-row{display:flex;align-items:center;gap:10px;margin:12px 0;font-size:12px}.environment-field small{font-size:11px;color:#94a3b8}.roles{display:flex;flex-wrap:wrap;gap:5px}.roles span{background:#eaf2ff;border-radius:4px;padding:4px 7px;font-size:10px;color:#2563eb}.events,.coupling{border:1px solid #e2e8f0;border-radius:9px;margin-top:18px;padding:18px}.events h3,.coupling h3{font-size:15px}.event-row{display:flex;flex-wrap:wrap;gap:9px;margin-top:12px;padding:14px;background:#f8fafc;border-radius:7px}.event-row>.el-input,.event-row>.el-select{width:190px}.event-row label{font-size:11px;color:#64748b;display:flex;align-items:center;gap:8px}.event-row .el-input-number{width:100px}.coupling-row{display:grid;grid-template-columns:130px 1fr;gap:15px;border-top:1px solid #e2e8f0;padding-top:12px;font-size:12px}.coupling-row p{margin-top:0}.footnote{color:#94a3b8!important;font-size:11px!important}@media(max-width:1000px){.layer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.layer-grid{grid-template-columns:1fr}.environment-model header{flex-wrap:wrap}}
</style>
